api_calls.code:
globalThis.targetApp = apps.find(a=>a.displayName==='MiniOrder');
if (!targetApp || targetApp.windows.length!==1) throw new Error('MiniOrder 目标窗口不唯一');
globalThis.targetWindow = await sky.get_window({id:targetApp.windows[0].id,app:targetApp.windows[0].app});
globalThis.state = await sky.get_window_state({window:targetWindow,include_screenshot:false,include_text:true});
globalThis.targetWindow=state.window;
nodeRepl.write(JSON.stringify(state.accessibility,null,2));

await sky.activate_window({window:targetWindow});
globalThis.targetWindow = await sky.get_window({id:targetApp.windows[0].id,app:targetApp.windows[0].app});
globalThis.state = await sky.get_window_state({window:targetWindow,include_screenshot:false,include_text:true});
globalThis.targetWindow=state.window;
nodeRepl.write(JSON.stringify(state.accessibility,null,2));

